select * from (values
('Scite','논문 인용이 연구 결과를 지지·반박하는지 문맥과 근거로 확인하는 AI #논문검색 #인용분석 #연구 #근거검증','Scite는 논문과 인용 문맥을 검색하고 후속 연구가 특정 결과를 지지·대조·언급하는지 Smart Citation으로 분류하며, 근거가 연결된 AI 답변과 참고문헌 검사를 제공합니다.','https://scite.ai/','https://scite.ai/favicon.ico','Paid',null,'무료 체험 · 개인·기관 요금은 공식 결제 또는 문의',array['무료 체험으로 검색과 Assistant 기능 일부를 확인할 수 있습니다.','개인 구독 가격은 로그인한 결제 화면에서 확인해야 합니다.','기관용 접근과 데이터 서비스는 별도 견적입니다.'],'USD','https://scite.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품 자료를 확인했습니다. 로그인 후 가격, 논문 분류 정확도와 API는 직접 테스트하지 않았습니다.',false,true,'https://api.scite.ai/','Native','specialized',array['Smart Citation 인용분석','근거 기반 AI 답변','참고문헌 검사'],array['전문 검색','대시보드','MCP·API'],array['지지·반박 인용 문맥 확인','답변과 실제 논문 근거 연결','대규모 학술 자료 검색'],array['논문 근거의 신뢰도를 확인하는 연구자','체계적 문헌 검토를 수행하는 사용자'],array['인용 분류는 자동 모델 결과이므로 원문 확인이 필요합니다.','개인 요금이 공개 페이지에서 명확히 표시되지 않을 수 있습니다.','논문 접근 권한은 출판사 계약에 따라 다릅니다.'],array['https://scite.ai/','https://scite.ai/pricing'],now(),now()),
('Litmaps','인용 관계로 관련 논문을 발견하고 연구 흐름을 시각적 지도로 관리하는 도구 #논문검색 #문헌연구 #시각화 #연구','Litmaps는 하나의 논문이나 주제에서 인용·참고문헌 관계를 따라 관련 연구를 찾아 시각적 지도로 구성하고, 새 논문 알림과 Zotero 동기화를 제공합니다.','https://www.litmaps.com/','https://www.litmaps.com/favicon.ico','Freemium','$0','Free 제한 지도 · Pro 연간 결제 월 $10부터',array['Free는 제한된 검색 입력과 Litmap·논문 수, 월간 알림을 제공합니다.','Pro는 연간 결제 월 $10부터 무제한 지도·논문과 고급 검색을 제공합니다.','교육 계정과 국가별 가격 할인으로 실제 결제액이 달라질 수 있습니다.'],'USD','https://www.litmaps.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격·도움말을 확인했습니다. 실제 문헌 검색 결과와 한국어 검색은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['인용 기반 논문 발견','연구 지도 시각화','신규 논문 모니터링'],array['Zotero 동기화','팀 협업','고급 검색 필터'],array['키워드 검색 밖의 연결 논문 발견','연구 분야 흐름 시각화','문헌 검토 지속 업데이트'],array['논문 탐색 범위를 넓히는 연구자','학위논문 문헌 지도를 만드는 학생'],array['무료 플랜의 지도와 논문 수가 제한됩니다.','메타데이터 연결이 논문의 품질을 보장하지 않습니다.','고급 기능과 일일 알림은 Pro가 필요합니다.'],array['https://www.litmaps.com/pricing','https://www.litmaps.com/features'],now(),now()),
('Motion','우선순위·마감·가용시간을 계산해 업무를 캘린더에 자동 배치하는 AI #일정관리 #프로젝트관리 #생산성 #회의록','Motion은 할 일, 프로젝트, 마감과 캘린더 일정을 분석해 작업 시간을 자동 배치하고 변경 시 다시 계획하며 AI 채팅·회의 기록·문서·워크플로를 통합합니다.','https://www.usemotion.com/','https://www.usemotion.com/favicon.ico','Paid','$19','무료 체험 · Pro AI 연간 결제 월 $19/좌석',array['무료 체험 후 유료 구독으로 전환되는 방식입니다.','Pro AI는 연간 결제 좌석당 월 $19에 월 7,500크레딧을 제공합니다.','Business AI는 연간 결제 좌석당 월 $29에 월 15,000크레딧과 고급 관리 기능을 제공합니다.'],'USD','https://www.usemotion.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 가격·도움말을 확인했습니다. 캘린더 연결과 자동 배치 품질은 직접 테스트하지 않았습니다.',false,true,'https://docs.usemotion.com/','Augmented','specialized',array['AI 일정 자동 배치','프로젝트·작업 관리','회의·문서 AI'],array['동적 재계획','워크플로','공개 API'],array['변경되는 일정을 자동 재계산','캘린더와 업무 계획 통합','개인·팀 작업량 관리'],array['할 일 우선순위를 일정으로 바꾸기 어려운 사용자','프로젝트와 팀 일정을 함께 관리하는 조직'],array['상시 무료 플랜이 아닌 체험판 중심입니다.','자동 일정은 정확한 작업시간·마감 입력에 크게 의존합니다.','캘린더 쓰기 권한과 자동 갱신 조건을 확인해야 합니다.'],array['https://www.usemotion.com/pricing','https://www.usemotion.com/help/time-management/auto-scheduling'],now(),now()),
('Taskade','프롬프트로 업무 앱·AI 에이전트·자동화와 협업 공간을 만드는 플랫폼 #AI에이전트 #AI앱개발 #워크플로 #생산성','Taskade는 자연어로 CRM·대시보드·포털 같은 앱을 만들고 파일과 프로젝트를 학습한 AI 에이전트, 다중 에이전트 팀과 예약 워크플로를 구성하는 협업 플랫폼입니다.','https://www.taskade.com/','https://www.taskade.com/favicon.ico','Freemium','$0','Free 1회 6,000크레딧 · Pro 월 $10',array['Free는 1회 6,000크레딧과 앱 3개를 제공하며 크레딧은 매월 갱신되지 않습니다.','Pro는 월 $10에 월 50,000크레딧, 사용자 10명과 무제한 앱·에이전트를 제공합니다.','Business는 월 $25에 월 150,000크레딧과 무제한 사용자를 제공합니다.'],'USD','https://www.taskade.com/pricing',now(),'Full Support',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 앱 생성, 한국어 품질과 개발자 API는 직접 테스트하지 않았습니다.',false,true,'https://docs.taskade.com/','Native','general',array['프롬프트 AI 앱 생성','AI 에이전트 팀','워크플로 자동화'],array['100개 이상 통합','업무·지식 관리','REST API·웹훅'],array['앱·에이전트·자동화를 한 공간에서 구축','무료 첫 앱 제작','팀 협업과 상시 실행'],array['내부 업무 도구를 빠르게 만드는 팀','여러 AI 에이전트를 업무에 연결하는 사용자'],array['무료 크레딧은 일회성으로 매월 갱신되지 않습니다.','긴 앱 생성과 복잡한 에이전트는 크레딧을 많이 소비합니다.','외부 앱 변경 작업에는 권한·승인 설계가 필요합니다.'],array['https://www.taskade.com/pricing'],now(),now()),
('Lindy','이메일·회의·업무 앱을 연결해 승인 기반으로 작업을 수행하는 AI 팀원 #AI에이전트 #이메일자동화 #회의록 #업무자동화','Lindy는 이메일 관리, 회의 준비·기록·후속 작업, CRM 업데이트와 조사 같은 업무를 수행하며 외부 영향이 있는 작업은 사용자 승인을 거치는 AI 업무 에이전트입니다.','https://www.lindy.ai/','https://www.lindy.ai/favicon.ico','Paid','$29.99','7일 체험 · Plus 월 $29.99/사용자',array['Slack으로 합류한 신규 사용자는 7일 무료 체험을 제공받습니다.','Plus는 사용자당 월 $29.99에 월 3,000크레딧을 제공합니다.','Pro는 월 $99.99에 15,000크레딧, Max는 월 $199.99에 35,000크레딧입니다.'],'USD','https://www.lindy.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 이메일 연결, 승인 흐름과 작업 성공률은 직접 테스트하지 않았습니다.',false,true,'https://docs.lindy.ai/','Native','general',array['업무 수행 AI 에이전트','이메일·회의 자동화','예약 루틴'],array['수천 개 통합','MCP','외부 작업 승인'],array['읽기와 실행 업무를 하나의 에이전트로 처리','외부 영향 작업 승인 절차','팀 크레딧 공동 사용'],array['이메일과 회의 후속 업무가 많은 팀','여러 업무 앱을 연결해 자동화하는 조직'],array['직접 가입은 무료 체험 없이 바로 과금될 수 있습니다.','월 크레딧은 이월되지 않습니다.','대규모 제작 작업은 수천 크레딧을 소비할 수 있습니다.'],array['https://www.lindy.ai/pricing','https://docs.lindy.ai/'],now(),now()),
('Bardeen','웹 데이터 수집·보강과 영업 업무를 브라우저 기반 에이전트로 자동화하는 AI #웹스크래핑 #영업자동화 #데이터수집 #AI에이전트','Bardeen은 웹 페이지에서 데이터를 추출하고 이메일·연락처를 보강해 스프레드시트와 CRM으로 전송하는 영업·운영 자동화와 AI 에이전트를 제공합니다.','https://www.bardeen.ai/','https://www.bardeen.ai/favicon.ico','Freemium','$0','Free 100크레딧 · Basic 월 $10',array['모든 계정에 무료 100크레딧을 제공하며 사용하지 않은 크레딧은 만료됩니다.','Basic은 월 $10에 월 100크레딧, Premium은 월 $50에 월 1,000크레딧입니다.','스크래핑·검색·AI 작업은 결과 행당 1크레딧, 보강은 행당 3크레딧입니다.'],'USD','https://www.bardeen.ai/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 실제 스크래핑 성공률과 외부 서비스 연결은 직접 테스트하지 않았습니다.',false,true,'https://docs.bardeen.ai/','Native','specialized',array['웹 스크래핑','리드 데이터 보강','영업 워크플로 자동화'],array['브라우저 확장','스프레드시트·CRM 연결','AI 도구'],array['웹 데이터를 업무 시스템으로 직접 이동','결과 행 기준 사용량','노코드 스크래퍼 제작'],array['리드 목록을 만드는 영업팀','반복적인 웹 데이터 입력을 줄이는 운영자'],array['사이트 구조 변경과 접근 제한으로 스크래퍼가 실패할 수 있습니다.','대량 보강은 행당 크레딧이 누적됩니다.','웹사이트 약관과 개인정보 수집 근거를 확인해야 합니다.'],array['https://www.bardeen.ai/pricing'],now(),now()),
('Clay','다수 데이터 제공자와 AI 조사를 결합해 영업 대상을 찾고 보강하는 GTM 플랫폼 #세일즈 #리드생성 #데이터보강 #AI에이전트','Clay는 150개 이상 데이터 제공자의 정보를 순차 조회하고 Claygent로 웹 조사를 수행해 잠재고객 데이터를 보강하며 CRM 동기화와 이메일 캠페인을 자동화합니다.','https://www.clay.com/','https://www.clay.com/favicon.ico','Freemium','$0','Free 제한 사용 · Launch 월 $185부터',array['Free는 제한된 데이터 보강, Claygent와 이메일 캠페인 기능을 제공합니다.','Launch는 월 $185부터 월 15,000 Actions와 2,500 Data Credits를 제공합니다.','Growth는 월 $495부터 CRM 동기화·HTTP API·웹훅과 더 높은 한도를 제공합니다.'],'USD','https://www.clay.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 자료를 확인했습니다. 데이터 정확도, 이메일 발송과 API 연동은 직접 테스트하지 않았습니다.',false,true,'https://docs.clay.com/','Augmented','specialized',array['영업 데이터 보강','Claygent 웹 조사','GTM 워크플로'],array['CRM·데이터웨어하우스 연결','이메일 캠페인','HTTP API·웹훅'],array['여러 데이터 제공자의 순차 조회','맞춤형 AI 리서치 필드','신호부터 캠페인까지 연결'],array['B2B 영업 대상 발굴 팀','대규모 잠재고객 데이터를 보강하는 조직'],array['Actions와 Data Credits가 별도로 계산됩니다.','CRM·HTTP API는 Growth 이상이 필요합니다.','연락처 수집·보강·발송 시 개인정보와 스팸 규정을 준수해야 합니다.'],array['https://www.clay.com/pricing'],now(),now()),
('Connected Papers','논문 간 유사성과 선행·후속 연구를 그래프로 탐색하는 문헌 발견 도구 #논문검색 #문헌연구 #시각화 #인용분석','Connected Papers는 시작 논문을 기준으로 유사한 연구를 그래프로 배치하고 주요 선행 연구와 후속 연구를 구분해 관련 문헌의 구조를 빠르게 탐색하도록 돕습니다.','https://www.connectedpapers.com/','https://www.connectedpapers.com/favicon.ico','Freemium','$0','Free 월 5개 그래프 · 유료 가격은 공식 결제 화면 확인',array['Free 계정은 매월 제한된 수의 그래프를 생성할 수 있습니다.','유료 Academic·Business 플랜은 더 많은 그래프와 기능을 제공합니다.','최신 정확한 가격은 로그인 후 공식 결제 화면에서 확인해야 합니다.'],'USD','https://www.connectedpapers.com/pricing',now(),'None',true,true,false,false,false,'official_sources','공식 제품·가격 페이지를 확인했습니다. 그래프 결과와 검색 범위는 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['유사 논문 그래프','선행·후속 연구 탐색','문헌 구조 시각화'],array['논문 목록 저장','그래프 공유','다중 시작 논문'],array['연구 분야를 시각적으로 파악','관련 논문을 빠르게 확장','핵심 선행·후속 연구 구분'],array['새 연구 분야를 탐색하는 학생·연구자','체계적 검색 전에 핵심 문헌을 찾는 사용자'],array['그래프 유사성이 논문의 품질이나 직접 인용 관계를 의미하지는 않습니다.','무료 월 그래프 수가 제한됩니다.','최신 가격은 로그인한 결제 화면 확인이 필요합니다.'],array['https://www.connectedpapers.com/','https://www.connectedpapers.com/pricing'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://scite.ai/','education'),('https://scite.ai/','search-data'),
('https://www.litmaps.com/','education'),('https://www.litmaps.com/','search-data'),
('https://www.usemotion.com/','productivity'),
('https://www.taskade.com/','productivity'),('https://www.taskade.com/','development'),
('https://www.lindy.ai/','productivity'),('https://www.lindy.ai/','business-marketing'),
('https://www.bardeen.ai/','business-marketing'),('https://www.bardeen.ai/','search-data'),
('https://www.clay.com/','business-marketing'),('https://www.clay.com/','search-data'),
('https://www.connectedpapers.com/','education'),('https://www.connectedpapers.com/','search-data')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
